async function loadSystemFonts() {
  if (fontLoadPromise) return fontLoadPromise;
  if (!window.desktop?.listSystemFonts) {
    fontLoadFailed = true;
    return;
  }
  fontLoadPromise = (async () => {
    const cachedFonts = readCachedFonts();
    if (cachedFonts?.length) {
      installedFonts = [...new Set(cachedFonts)].sort((a, b) => a.localeCompare(b));
      updateAllFontSuggestions();
    }
    try {
      const fonts = await window.desktop.listSystemFonts();
      if (!Array.isArray(fonts) || fonts.length === 0) {
        fontLoadFailed = !installedFonts.length;
        if (!installedFonts.length) fontPickers.forEach((picker) => { picker.status.textContent = counterText('fontName'); });
        return null;
      }
      installedFonts = [...new Set(fonts)].sort((a, b) => a.localeCompare(b));
      fontLoadFailed = false;
      updateAllFontSuggestions();
      writeCachedFonts(fonts);
      return fonts;
    } catch {
      fontLoadFailed = !installedFonts.length;
      fontPickers.forEach((picker) => { picker.status.textContent = counterText('fontName'); });
      return null;
    }
  })();
  return fontLoadPromise;
}

