let availableUpdate = null;
let linuxUpdate = null;
let linuxUpdateInProgress = false;
let linuxUpdateInstalled = false;
let updateCheckInProgress = false;
const releasePage = 'https://github.com/wmarklloyd/Markdown-Vision/releases/latest';

function versionParts(value) {
  const match = /^v?(\d+)\.(\d+)\.(\d+)$/.exec(value);
  return match ? match.slice(1).map(Number) : null;
}

function findLinuxUpdateAsset(assets, architecture, isFedora) {
  const compatible = (assets || []).filter((item) => {
    const name = item.name.toLowerCase();
    return name.includes(`-${architecture}.`) && (isFedora
      ? name.includes('fedora') || !name.includes('ubuntu')
      : !name.includes('fedora'));
  });
  if (isFedora) return compatible.find((item) => /\.rpm$/i.test(item.name));
  return compatible.find((item) => /\.deb$/i.test(item.name))
    || (architecture === 'x86_64' ? compatible.find((item) => /\.appimage$/i.test(item.name)) : undefined);
}

async function fetchReleaseJson(url, accept) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 5000);
  try {
    const response = await fetch(url, { signal: controller.signal, headers: { Accept: accept } });
    if (!response.ok) throw new Error('Release check failed');
    return await response.json();
  } finally {
    clearTimeout(timeout);
  }
}

async function fetchUpdateReleases(isWindowsUpdater) {
  const api = 'https://api.github.com/repos/wmarklloyd/Markdown-Vision/releases';
  try {
    const releases = await fetchReleaseJson(api + (isWindowsUpdater ? '/latest' : '?per_page=100'),
      'application/vnd.github+json');
    if (isWindowsUpdater && versionParts(releases?.tag_name || '')) return [releases];
    if (!isWindowsUpdater && Array.isArray(releases)) return releases;
    throw new Error('Unrecognized release information');
  } catch {
    // Raw GitHub files are served separately from the rate-limited release API.
    // Keep the feed in sync with SHA256SUMS.txt when publishing a stable release.
    const feed = await fetchReleaseJson(
      'https://raw.githubusercontent.com/wmarklloyd/Markdown-Vision/master/release-feed.json',
      'application/json');
    if (typeof feed?.version !== 'string' || !/^\d{1,9}\.\d{1,9}\.\d{1,9}$/.test(feed.version)
        || !feed.assets || typeof feed.assets !== 'object' || Array.isArray(feed.assets)) {
      throw new Error('Unrecognized release information');
    }
    const tag = 'v' + feed.version;
    const assets = Object.entries(feed.assets)
      .filter(([name, digest]) => /^[A-Za-z0-9._-]+$/.test(name)
        && name.includes('-' + feed.version + '-') && typeof digest === 'string' && /^[0-9a-f]{64}$/i.test(digest))
      .map(([name, digest]) => ({
        name,
        browser_download_url: 'https://github.com/wmarklloyd/Markdown-Vision/releases/download/' + tag + '/' + name,
        digest: 'sha256:' + digest.toLowerCase(),
      }));
    if (!assets.length) throw new Error('No release assets');
    return [{ tag_name: tag, assets }];
  }
}

async function checkForUpdates() {
  const latestLabel = document.getElementById('latestVersion');
  const updateLink = document.getElementById('updateLink');
  const retryButton = document.getElementById('retryUpdateCheck');
  if (linuxUpdateInstalled || updateCheckInProgress) return;
  updateCheckInProgress = true;
  const installed = versionParts(document.getElementById('installedVersion').dataset.version);
  latestLabel.textContent = interfaceText('Latest version: checking…');
  retryButton.hidden = true;
  updateLink.hidden = true;
  updateLink.href = releasePage;
  updateLink.textContent = interfaceText('Update');
  availableUpdate = null;
  linuxUpdate = null;
  try {
    const isWindowsUpdater = Boolean(window.desktop?.installUpdate);
    const releases = await fetchUpdateReleases(isWindowsUpdater);
    if (!installed) throw new Error('Unrecognized installed version');

    if (isWindowsUpdater) {
      const release = releases[0];
      const latest = versionParts(release?.tag_name || '');
      if (!latest) throw new Error('Unrecognized version');
      latestLabel.textContent = interfaceText('Latest version: {version}', { version: latest.join('.') });
      const difference = latest.findIndex((part, index) => part !== installed[index]);
      updateLink.hidden = difference < 0 || latest[difference] < installed[difference];
      if (!updateLink.hidden) {
        const version = latest.join('.');
        const architecture = await window.desktop.updateArchitecture();
        if (!['x64', 'arm64'].includes(architecture)) throw new Error('Unsupported architecture');
        const suffix = architecture === 'arm64' ? '-Windows-ARM64' : '-Intel-AMD-x64';
        const asset = release.assets?.find((item) => item.name === `Markdown-Vision-Native-Setup-${version}${suffix}.exe`);
        const digest = /^sha256:([0-9a-f]{64})$/.exec(asset?.digest || '');
        if (!digest) throw new Error('Installer verification is unavailable');
        availableUpdate = { version, digest: digest[1] };
      }
      return;
    }

    const platform = await window.desktop?.getPlatformInfo?.();
    if (!['linux', 'macos'].includes(platform?.platform)) throw new Error('Unsupported platform');
    const architecture = platform.architecture === 'x86_64' ? 'x86_64'
      : platform.architecture === 'aarch64' ? 'aarch64' : null;
    if (!architecture) throw new Error('Unsupported architecture');
    const isFedora = ['fedora', 'rhel', 'centos', 'rocky', 'almalinux'].includes(platform.distribution);
    const candidates = releases.map((release) => ({
      release,
      version: versionParts(release.tag_name || ''),
      asset: platform.platform === 'macos'
        ? release.assets?.find((item) => /\.dmg$/i.test(item.name))
        : findLinuxUpdateAsset(release.assets, architecture, isFedora),
    })).filter(({ version, asset, release }) => {
      if (!version || !asset || release.draft || release.prerelease) return false;
      const difference = version.findIndex((part, index) => part !== installed[index]);
      return difference >= 0 && version[difference] > installed[difference];
    }).sort((a, b) => {
      for (let i = 0; i < 3; i += 1) {
        if (a.version[i] !== b.version[i]) return b.version[i] - a.version[i];
      }
      return 0;
    });
    const candidate = candidates[0];
    if (!candidate) {
      latestLabel.textContent = interfaceText('Latest compatible version: {version}', { version: installed.join('.') });
      updateLink.hidden = true;
      return;
    }
    latestLabel.textContent = interfaceText('Latest compatible version: {version}', { version: candidate.version.join('.') });
    updateLink.href = candidate.asset.browser_download_url;
    const digest = /^sha256:([0-9a-f]{64})$/i.exec(candidate.asset.digest || '');
    if (platform.platform === 'linux' && (isFedora ? /\.rpm$/i : /\.deb$/i).test(candidate.asset.name)
        && digest && window.desktop?.installLinuxUpdate) {
      linuxUpdate = { version: candidate.version.join('.'), digest: digest[1] };
    }
    updateLink.textContent = interfaceText(linuxUpdate ? 'Upgrade Markdown Vision'
      : platform.platform === 'macos' ? 'Download macOS update' : 'Download Linux update');
    updateLink.hidden = false;
  } catch (error) {
    const specific = ['Unsupported architecture', 'Unsupported platform', 'Installer verification is unavailable'];
    latestLabel.textContent = interfaceText(specific.includes(error?.message) ? error.message
      : 'Release check failed');
    updateLink.hidden = false;
    retryButton.hidden = false;
  } finally {
    updateCheckInProgress = false;
  }
}

document.getElementById('retryUpdateCheck').addEventListener('click', () => void checkForUpdates());
document.querySelector('.about-menu').addEventListener('toggle', (event) => {
  if (event.currentTarget.open) setTimeout(() => void checkForUpdates(), 0);
});
document.getElementById('updateLink').addEventListener('click', async (event) => {
  if (linuxUpdate) {
    event.preventDefault();
    if (linuxUpdateInProgress || window.markdownVisionReader.isSaving?.()) return;
    linuxUpdateInProgress = true;
    const link = event.currentTarget;
    const status = document.getElementById('latestVersion');
    const update = linuxUpdate;
    link.hidden = true;
    status.textContent = interfaceText('Downloading and verifying the update. You may be asked to authenticate.');
    try {
      await window.desktop.installLinuxUpdate(update.version, update.digest);
      linuxUpdate = null;
      linuxUpdateInstalled = true;
      status.textContent = interfaceText('Update installed. Restart to use the new version.');
      document.getElementById('restartAfterUpdate').hidden = !window.desktop?.restartAfterUpdate;
    } catch (error) {
      setLocalizedErrorStatus(status, 'Update failed: {error}', error);
      link.hidden = false;
    } finally {
      linuxUpdateInProgress = false;
    }
    return;
  }
  if (!window.desktop?.installUpdate || !availableUpdate) return;
  event.preventDefault();
  if (window.markdownVisionReader.isSaving?.()) return;
  const link = event.currentTarget;
  const status = document.getElementById('latestVersion');
  link.hidden = true;
  status.textContent = interfaceText('Downloading and verifying update…');
  let started = false;
  try {
    started = await window.desktop.installUpdate(availableUpdate.version, availableUpdate.digest);
  } catch {
    // A failed native bridge request needs the same visible recovery as a
    // reported installer failure, rather than leaving the progress message up.
  }
  if (started) status.textContent = interfaceText('Installer started.');
  else {
    status.textContent = interfaceText('Could not download, verify, or start the installer. Please try again.');
    link.hidden = false;
  }
});

document.getElementById('restartAfterUpdate').addEventListener('click', async (event) => {
  if (window.markdownVisionReader.isSaving?.()) return;
  if (window.markdownVisionReader.hasUnsavedChanges?.()) {
    const discard = window.desktop?.confirmDiscard
      ? await window.desktop.confirmDiscard('quit')
      : window.confirm(interfaceText('Discard unsaved changes and restart?'));
    if (!discard) return;
  }
  const button = event.currentTarget;
  button.disabled = true;
  try {
    await window.desktop.restartAfterUpdate(window.markdownVisionReader.getDocument()?.documentId || null);
  } catch (error) {
    setLocalizedErrorStatus(document.getElementById('latestVersion'), 'Could not restart: {error}', error);
    button.disabled = false;
  }
});

async function offerMarkdownAssociationDuringSetup() {
  const invoke = window.__TAURI__?.core?.invoke;
  if (typeof invoke !== 'function') return;
  const key = 'markdown-vision-association-setup';
  try {
    if (localStorage.getItem(key)) return;
    if (await invoke('is_markdown_default')) {
      localStorage.setItem(key, 'already-default');
      return;
    }
  } catch {
    return;
  }
  const accepted = window.confirm(interfaceText('Would you like Markdown Vision to open Markdown files by default?'));
  if (!accepted) {
    try { localStorage.setItem(key, 'declined'); } catch {}
    return;
  }
  try {
    await invoke('associate_markdown');
    localStorage.setItem(key, 'accepted');
  } catch {
    window.alert(interfaceText('Could not set Markdown Vision as the default Markdown app.'));
  }
}

window.addEventListener('load', async () => {
  try {
    const initialDocument = await window.desktop?.getInitialDocument?.();
    if (!currentDocument && initialDocument) showDocument(initialDocument.content, initialDocument.name, initialDocument.documentId, initialDocument.imageBase);
  } catch (error) {
    await reportDocumentOpenError(error);
  } finally {
    void offerMarkdownAssociationDuringSetup();
  }
});
